import { createClient } from '@supabase/supabase-js'
import Link from 'next/link'

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    )

    // Safe fetch - table එකක් නැත්තන් error නොදී null දෙන function එක
    async function safeFetch(table: string, query: any = null) {
      try {
          let req = supabase.from(table).select('*')
              if (query) req = query(req)
                  const { data, error } = await req
                      if (error) {
                            console.log(`Table ${table} not found or error:`, error.message)
                                  return []
                                      }
                                          return data || []
                                            } catch {
                                                return []
                                                  }
                                                  }

                                                  export default async function HomePage() {
                                                    // 1. ඔක්කොම Tables Parallel Fetch කරනවා
                                                      const [heroData, productsData, categoriesData, settingsData] = await Promise.all([
                                                          safeFetch('hero_sections', (q: any) => q.eq('is_visible', 1).limit(1)),
                                                              safeFetch('products', (q: any) => q.eq('is_active', true).limit(8)),
                                                                  safeFetch('categories', (q: any) => q.limit(6)),
                                                                      safeFetch('site_settings', (q: any) => q.limit(1)),
                                                                        ])

                                                                          const hero = heroData[0] || null
                                                                            const products = productsData.length > 0 ? productsData : []
                                                                              const categories = categoriesData.length > 0 ? categoriesData : []
                                                                                const settings = settingsData[0] || null

                                                                                  // Hero data - ඔයාගේ table එකේ තියෙන නම් වලට support
                                                                                    const title = hero?.title || hero?.main_title || 'Aroma Lab'
                                                                                      const subtitle = hero?.subtitle || 'Fine Fragrances'
                                                                                        const desc = hero?.description || 'Discover your signature scent. Premium, long-lasting, crafted in Sri Lanka.'
                                                                                          const heroImg = hero?.image_url || hero?.hero_image || ''
                                                                                            const btnText = hero?.primary_button || hero?.button_text || 'Shop Now'
                                                                                              const btnUrl = hero?.button_url || '/products'

                                                                                                return (
                                                                                                    <main className="min-h-screen bg-white text-black selection:bg-black selection:text-white">
                                                                                                          {/* HERO SECTION - hero_sections table එකෙන් */}
                                                                                                                <section className="max-w-[1320px] mx-auto px-6 md:px-10 py-10 md:py-20">
                                                                                                                        <div className="flex flex-col-reverse md:flex-row items-center gap-10 md:gap-16">
                                                                                                                                  <div className="flex-1">
                                                                                                                                              <p className="text-[12px] tracking-[0.45em] text-neutral-400 uppercase">{subtitle}</p>
                                                                                                                                                          <h1 className="mt-5 text-[54px] md:text-[92px] font-black leading-[0.85] tracking-tighter">
                                                                                                                                                                        {title.split(' ').map((w: string, i: number) => (
                                                                                                                                                                                        <span key={i} className="block">{w}</span>
                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                  </h1>
                                                                                                                                                                                                                              <p className="mt-6 max-w-[440px] text-[15px] leading-6 text-neutral-500">{desc}</p>
                                                                                                                                                                                                                                          <div className="mt-8 flex gap-3">
                                                                                                                                                                                                                                                        <Link href={btnUrl} className="bg-black text-white px-8 py-4 rounded-full text-sm font-medium hover:bg-neutral-800 transition">
                                                                                                                                                                                                                                                                        {btnText}
                                                                                                                                                                                                                                                                                      </Link>
                                                                                                                                                                                                                                                                                                    <Link href="/about" className="bg-neutral-100 text-black px-8 py-4 rounded-full text-sm font-medium hover:bg-neutral-200 transition">
                                                                                                                                                                                                                                                                                                                    Our Story
                                                                                                                                                                                                                                                                                                                                  </Link>
                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                  <div className="flex-1 w-full">
                                                                                                                                                                                                                                                                                                                                                                              <div className="relative w-full h-[520px] md:h-[680px] bg-[#f6f4f1] rounded-[36px] overflow-hidden">
                                                                                                                                                                                                                                                                                                                                                                                            {heroImg ? (
                                                                                                                                                                                                                                                                                                                                                                                                            // eslint-disable-next-line @next/next/no-img-element
                                                                                                                                                                                                                                                                                                                                                                                                                            <img src={heroImg} alt={title} className="w-full h-full object-cover" />
                                                                                                                                                                                                                                                                                                                                                                                                                                          ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="w-full h-full flex items-center justify-center text-neutral-400 text-sm">Add image from Admin - hero_sections</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {/* CATEGORIES - categories table එකෙන් auto */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {categories.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <section className="max-w-[1320px] mx-auto px-6 md:px-10 pb-16">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex gap-3 overflow-x-auto scrollbar-hide">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {categories.map((cat: any) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Link key={cat.id} href={`/products?category=${cat.slug || cat.id}`} className="shrink-0 px-6 py-3 rounded-full bg-neutral-100 text-sm hover:bg-black hover:text-white transition">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {cat.name || cat.title}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* PRODUCTS - products table එකෙන් */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <section className="max-w-[1320px] mx-auto px-6 md:px-10 pb-20">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex items-end justify-between mb-8">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h2 className="text-3xl md:text-5xl font-bold tracking-tight">Best Sellers</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Link href="/products" className="text-sm underline underline-offset-4">View all</Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {products.length > 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {products.map((p: any) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Link key={p.id} href={`/products/${p.slug || p.id}`} className="group">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="aspect-[3/4] bg-neutral-100 rounded-[24px] overflow-hidden">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {/* eslint-disable-next-line @next/next/no-img-element */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <img src={p.image_url || p.image || heroImg} alt={p.name || p.title} className="w-full h-full object-cover group-hover:scale-105 transition duration-500" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="mt-3 px-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p className="text-sm font-medium">{p.name || p.title}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="text-sm text-neutral-500">Rs. {p.price || '2,500'}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="bg-neutral-50 rounded-[24px] p-10 text-center text-neutral-500 text-sm">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            No products yet. Add products in Supabase - `products` table (name, price, image_url, is_active)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {/* FOOTER SETTINGS - site_settings table එකෙන් */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <footer className="border-t border-neutral-100">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="max-w-[1320px] mx-auto px-6 md:px-10 py-10 flex justify-between text-xs text-neutral-400">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p>© {new Date().getFullYear()} {settings?.site_name || 'AROMA'} - All rights reserved</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p>{settings?.tagline || 'Crafted in Colombo'}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </footer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                